// ===== vostd full-run contract shape models =====
// Frozen source: /tmp/vostd-43da079-ktest-chan/ostd/src (rev 43da0797bbfa)
// Inventory: research/experiments/spec-quality-two-day/guard-return-inventory.csv
//   rows with entry_precondition_vacuous=true (7 rows, all external_body stubs)
// All shape entries are SHAPE REPRODUCTIONS: tracked parameters
// (Tracked<&mut CursorOwner> / NodeOwner / OwnerSubtree / MetaRegionOwners /
// Guards / PointsTo / Tracked<&NodeOwner>) are abstracted to opaque usize ids;
// scalar comparisons are transcribed mechanically; predicates over ghost
// structure that cannot be expressed over plain parameters are declared as
// named uninterp spec fns below (constraint structure preserved by name, body
// abstract — see EXTRACTION.md for the clause-by-clause mapping).

// mm/page_table/node/mod.rs lock & make_guard_unchecked:
//   self.inner@.invariants(*owner),
//   self.inner@.external_meta_wf(owner.frame_permission.resource(), ()),
//   old(guards).unlocked(owner.slot_vaddr())
pub uninterp spec fn node_invariants(node_id: usize, owner_id: usize) -> bool;
pub uninterp spec fn external_meta_wf(node_id: usize, owner_id: usize) -> bool;
pub uninterp spec fn guards_unlocked(guards_id: usize, slot_vaddr: usize) -> bool;

// mm/page_table/node/entry.rs alloc_if_none / split_if_mapped_huge /
// alloc_absent_child: predicates over CursorOwner/NodeOwner/MetaRegionOwners
// ghost structure (invariants, inv, path, metaregion soundness, count windows,
// match_pte, guard relations, slot maps)
pub uninterp spec fn entry_invariants(entry_id: usize, owner_id: usize, regions_id: usize) -> bool;
pub uninterp spec fn owner_inv(owner_id: usize) -> bool;
pub uninterp spec fn node_matching(entry_id: usize, owner_id: usize, parent_owner_id: usize) -> bool;
pub uninterp spec fn entry_wf(entry_id: usize, owner_id: usize) -> bool;
pub uninterp spec fn relate_guard(owner_id: usize, entry_id: usize) -> bool;
pub uninterp spec fn metaregion_sound(owner_id: usize, regions_id: usize) -> bool;
pub uninterp spec fn metaregion_sound_node(owner_id: usize, regions_id: usize) -> bool;
pub uninterp spec fn regions_inv(regions_id: usize) -> bool;
pub uninterp spec fn in_count_window(level: usize, idx: usize) -> bool;
pub uninterp spec fn match_pte(owner_id: usize, parent_owner_id: usize, idx: usize, owner_parent_level: usize) -> bool;
pub uninterp spec fn slots_contains_key(regions_id: usize, slot_index: usize) -> bool;

// mm/page_table/cursor/locking.rs try_traverse_and_lock_subtree_root:
//   old(cursor_own).continuations.dom().contains(NR_LEVELS - 1),
//   old(cursor_own).continuations[NR_LEVELS - 1].all_some()
pub uninterp spec fn cont_dom_contains(cursor_own_id: usize, level: usize) -> bool;
pub uninterp spec fn cont_all_some(cursor_own_id: usize, level: usize) -> bool;

// ---- mechanical scalar transcriptions (spec arithmetic is mathematical in
// verus, so e.g. level < inc_levels - 1 is well-defined for inc_levels == 0) ----
pub open spec fn perm_matches_cell(perm_id: usize, mutex_id: usize) -> bool {
    perm_id == mutex_id
}
pub open spec fn cursor_level_eq_nr_levels(cursor_level: usize, nr_levels: usize) -> bool {
    cursor_level == nr_levels
}
pub open spec fn path_len_eq_level(path_len: usize, level: usize) -> bool {
    path_len == level
}
pub open spec fn level_lt_inc_minus_1(level: usize, inc_levels: usize) -> bool {
    level < inc_levels - 1
}
pub open spec fn levels_sum_eq_inc(level_a: usize, level_b: usize, inc_levels: usize) -> bool {
    level_a + level_b == inc_levels
}
pub open spec fn parent_level_eq_owner_parent_level(parent_level: usize, owner_parent_level: usize) -> bool {
    parent_level == owner_parent_level
}
pub open spec fn level_lt_nr_levels(level: usize, nr_levels: usize) -> bool {
    level < nr_levels
}
pub open spec fn parent_level_gt_1(parent_level: usize) -> bool {
    parent_level > 1
}
pub open spec fn idx_lt_nr_entries(idx: usize, nr_entries: usize) -> bool {
    idx < nr_entries
}
// split_if_mapped_huge:
//   old(owner).value().is_frame() && old(parent_owner).level() > 1 ==>
//       old(owner).value().metaregion_sound(*old(regions))
pub open spec fn frame_split_metaregion(owner_is_frame: bool, parent_level: usize, owner_id: usize, regions_id: usize) -> bool {
    !(owner_is_frame && parent_level > 1) || metaregion_sound(owner_id, regions_id)
}

// ---- negative-control models ----
pub open spec fn val_in_domain(val_id: usize) -> bool {
    val_id < 8
}
pub open spec fn i_lt_len(i: usize, len: usize) -> bool {
    i < len
}
pub open spec fn i_ge_len(i: usize, len: usize) -> bool {
    i >= len
}
